var allZones = [...act1Zones, ...act2Zones, ...act3Zones, ...act4Zones, ...act5Zones];
var byId = (list) => Object.fromEntries(list.map((x) => [x.id, x]));
var content = {
  B,
  classes: { reaver, elementalist, gravecaller, ranger, templar },
  classOrder: ["reaver", "elementalist", "gravecaller", "ranger", "templar"],
  monsters: byId([...act1Monsters, ...act2Monsters, ...act3Monsters, ...act4Monsters, ...act5Monsters]),
  modifiers: byId([...championModifiers, ...lateModifiers]),
  bosses: byId([...act1Bosses, ...act2Bosses, ...act3Bosses, ...act4Bosses, ...act5Bosses]),
  zones: byId(allZones),
  zoneOrder: allZones.map((z) => z.id),
  acts: [1, 2, 3, 4, 5],
  bases: byId(bases),
  baseList: bases,
  affixes: byId(affixes),
  affixList: affixes,
  rareNames: { a: RARE_NAME_A, b: RARE_NAME_B },
  gemTypes,
  gemQualities: GEM_QUALITIES,
  runes: byId(runes),
  runeOrder: runes.map((r) => r.id),
  runewords: byId(runewords),
  uniques: byId(uniques),
  sets: byId(sets),
  setPieces: Object.fromEntries(sets.flatMap((s) => s.pieces.map((p) => [p.id, { ...p, set: s.id }]))),
  mercs: byId(mercs),
  mercOrder: mercs.map((m) => m.id),
  MERC_SLOTS,
  EQUIP_SLOTS,
  ARMOR_SLOTS
};
var SYN_ATTACK = 3;
var SYN_SPELL = 4;
var SYN_PICK = { fire_arrow: ["frost_arrow"], blight_volley: ["venom_tip"], bone_storm: ["bone_dart", "bone_mage"], plague_cloud: ["blight_touch"], blight_touch: ["soul_siphon"] };
var dealsDamage = (s) => s.type === "active" && (s.effect?.dmgMin != null || s.effect?.dmgPct != null || s.effect?.kind === "summon");
for (const cls of Object.values(content.classes)) {
  for (const tree of cls.trees) {
    const list = cls.skills.filter((s) => s.tree === tree).sort((a, b) => a.reqLevel - b.reqLevel);
    list.forEach((s, i) => {
      s.tier = i;
      if (i > 0) s.pre = list[i - 1].id;
    });
    list.forEach((s, i) => {
      if (!dealsDamage(s)) return;
      const kind = s.effect.kind === "attack" ? "attack" : "pct";
      const atk = s.requires === "bow" ? SYN_ATTACK : SYN_ATTACK - 1;
      const make = (id) => kind === "attack" ? { skill: id, param: "dmgPct", perPoint: atk } : { skill: id, param: "pct", perPoint: SYN_SPELL };
      let syn = (s.synergies ?? []).map((x) => x.param === "dmgPctBonus" ? { skill: x.skill, param: "pct", perPoint: SYN_SPELL } : x.param === "dmgPct" ? { ...x, perPoint: atk } : x);
      const picked = SYN_PICK[s.id];
      if (picked) syn = picked.map(make);
      else if (i >= 2) {
        for (const h of list.slice(0, i).filter(dealsDamage).reverse()) if (syn.length < 2 && !syn.some((x) => x.skill === h.id)) syn.push(make(h.id));
      }
      syn = syn.filter((x) => x.skill !== s.id).slice(0, 2);
      if (syn.length) s.synergies = syn;
      else delete s.synergies;
    });
  }
}

